-- Generated by drizzle-kit, then edited by hand. The rebuild of order_line is replaced by ALTER TABLE ADD COLUMN with
-- its CHECK, which SQLite tests against the rows already there (none has a total), and drizzle-kit's PRAGMA pair goes
-- with it. Then guards that keep the rules in the database as well as in code, each a trigger, so no table is rebuilt:
-- a message is settled once whatever the order its readings' ids fall in; an order line never names a product deleted
-- or merged away (the trash would delete it for good from under the order); an order or reminder never comes back
-- while its customer is in the trash; a person's notification settings are added once, so the second of two first
-- changes is stale rather than a fault. Every trigger raises stale_version, which the app reads as "changed elsewhere".
-- The schema tests fail if any of it goes missing.
ALTER TABLE `order_line` ADD `total` integer CONSTRAINT "order_line_total_fits" CHECK("total" is null or ("total" between 0 and 1000000000000 and abs("total" - "quantity" * "unit_price") * 2 <= "quantity"));--> statement-breakpoint
CREATE INDEX `sales_order_by_capture` ON `sales_order` (`capture_id`);--> statement-breakpoint
CREATE INDEX `reminder_by_capture` ON `reminder` (`capture_id`);
--> statement-breakpoint
DROP TRIGGER `interpretation_once_settled`;
--> statement-breakpoint
CREATE TRIGGER `interpretation_once_settled` BEFORE INSERT ON `interpretation`
WHEN EXISTS (
	SELECT 1 FROM `interpretation`
	WHERE `capture_id` = NEW.`capture_id` AND `outcome` IN ('order', 'reminder', 'note')
)
BEGIN
	SELECT RAISE(ABORT, 'stale_version');
END;
--> statement-breakpoint
CREATE TRIGGER `order_line_names_kept_product` BEFORE INSERT ON `order_line`
WHEN (SELECT `deleted_at` IS NOT NULL OR `merged_into_id` IS NOT NULL FROM `product` WHERE `id` = NEW.`product_id`)
BEGIN
	SELECT RAISE(ABORT, 'stale_version');
END;
--> statement-breakpoint
CREATE TRIGGER `sales_order_comes_back_with_its_customer` BEFORE UPDATE OF `deleted_at` ON `sales_order`
WHEN OLD.`deleted_at` IS NOT NULL AND NEW.`deleted_at` IS NULL
	AND (SELECT `deleted_at` FROM `customer` WHERE `id` = NEW.`customer_id`) IS NOT NULL
BEGIN
	SELECT RAISE(ABORT, 'stale_version');
END;
--> statement-breakpoint
CREATE TRIGGER `reminder_comes_back_with_its_customer` BEFORE UPDATE OF `deleted_at` ON `reminder`
WHEN OLD.`deleted_at` IS NOT NULL AND NEW.`deleted_at` IS NULL AND NEW.`customer_id` IS NOT NULL
	AND (SELECT `deleted_at` FROM `customer` WHERE `id` = NEW.`customer_id`) IS NOT NULL
BEGIN
	SELECT RAISE(ABORT, 'stale_version');
END;
--> statement-breakpoint
CREATE TRIGGER `notification_preference_added_once` BEFORE INSERT ON `notification_preference`
WHEN EXISTS (SELECT 1 FROM `notification_preference` WHERE `account_id` = NEW.`account_id`)
BEGIN
	SELECT RAISE(ABORT, 'stale_version');
END;
